//! dc_test — differential test: replay golden vectors generated by the
//! Python oracle (h264_math.py) and fail on ANY divergence.
//!
//! Usage: cargo run --release --bin dc_test

use std::fs;
use std::path::Path;

use h264core::{is_keyframe, split_nals, Demuxer};

fn unhex(s: &str) -> Vec<u8> {
    if s.is_empty() {
        return Vec::new();
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("bad hex"))
        .collect()
}

fn main() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden_vectors.txt");
    let data = fs::read_to_string(&path).expect("golden_vectors.txt missing — run _research/gen_goldens.py first");
    let mut fails = 0u32;
    let mut n_frames = 0u32;
    let mut n_cases = 0u32;

    let mut lines = data.lines().peekable();
    while let Some(line) = lines.next() {
        let mut it = line.split_whitespace();
        match it.next() {
            Some("FRAME") => {
                n_frames += 1;
                let frame = unhex(it.next().unwrap_or(""));
                // oracle expectation: NAL lines follow, then KF
                let mut expect: Vec<(u8, u8, Vec<u8>)> = Vec::new();
                let mut expect_kf = false;
                for l in lines.by_ref() {
                    let mut it2 = l.split_whitespace();
                    match it2.next() {
                        Some("NAL") => {
                            let t: u8 = it2.next().unwrap().parse().unwrap();
                            let r: u8 = it2.next().unwrap().parse().unwrap();
                            expect.push((t, r, unhex(it2.next().unwrap_or(""))));
                        }
                        Some("KF") => {
                            expect_kf = it2.next().unwrap() == "1";
                            break;
                        }
                        _ => break,
                    }
                }

                let got = split_nals(&frame);
                let got_kf = is_keyframe(&frame);
                if got.len() != expect.len() {
                    println!("FAIL frame#{n_frames}: NAL count {} != {}", got.len(), expect.len());
                    fails += 1;
                    continue;
                }
                for (i, (g, e)) in got.iter().zip(expect.iter()).enumerate() {
                    if g.nal_type != e.0 || g.ref_idc != e.1 || g.rbsp != e.2 {
                        println!("FAIL frame#{n_frames} nal#{i}: got ({},{},{:x?}) want ({},{},{:x?})", g.nal_type, g.ref_idc, g.rbsp, e.0, e.1, e.2);
                        fails += 1;
                    }
                }
                if got_kf != expect_kf {
                    println!("FAIL frame#{n_frames}: keyframe {got_kf} != {expect_kf}");
                    fails += 1;
                }
            }
            Some("DEMUXCASE") => {
                n_cases += 1;
                let mut chunks: Vec<Vec<u8>> = Vec::new();
                let mut err = None;
                let mut outs: Vec<(u64, Vec<u8>)> = Vec::new();
                for l in lines.by_ref() {
                    let mut it2 = l.split_whitespace();
                    match it2.next() {
                        Some("CHUNK") => chunks.push(unhex(it2.next().unwrap_or(""))),
                        Some("ERR") => {
                            err = Some((it2.next().unwrap().parse::<u64>().unwrap(),
                                        it2.next().unwrap().parse::<usize>().unwrap()));
                        }
                        Some("OUT") => outs.push((it2.next().unwrap().parse().unwrap(),
                                                  unhex(it2.next().unwrap_or("")))),
                        Some("ENDCASE") => break,
                        _ => {}
                    }
                }
                let mut d = Demuxer::new();
                let mut got_outs: Vec<(u64, Vec<u8>)> = Vec::new();
                let mut got_err = None;
                for c in &chunks {
                    match d.feed(c) {
                        Ok(fs) => got_outs.extend(fs),
                        Err(e) => {
                            got_err = Some(match e {
                                h264core::DemuxError::InsaneFrame { pts, length } => (pts, length),
                            });
                            break;
                        }
                    }
                }
                if got_err != err {
                    println!("FAIL demux#{n_cases}: err {got_err:?} != {err:?}");
                    fails += 1;
                } else if got_err.is_none() && got_outs != outs {
                    println!("FAIL demux#{n_cases}: frames diverge ({} vs {})", got_outs.len(), outs.len());
                    fails += 1;
                }
            }
            _ => {}
        }
    }

    println!("GOLDEN VERDICT: {fails} failures across {n_frames} frames + {n_cases} demux cases");
    if fails == 0 {
        println!("Rust port == Python oracle, byte for byte. The transplant is honest.");
        std::process::exit(0);
    }
    std::process::exit(1);
}
